describe('Notification Bell Badge Count', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display correct badge count on notification bell icon when notifications are present', () => {
    // Setup: Create 3 notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');
    cy.get('[data-testid="notification-count"]').should('be.visible');
    cy.get('[data-testid="notification-count"]').should('contain', '3');
    cy.get('[data-testid="notification-bell-icon"]').should('be.visible');
    cy.get('[data-testid="notification-bell-icon"]').should('have.class', 'badge');
    cy.get('[data-testid="notification-bell-icon"]').should('have.attr', 'aria-label', 'Notification bell');
    cy.get('[data-testid="notification-bell-icon"]').should('have.attr', 'aria-badge', '3');
    cy.get('[data-testid="notification-bell-icon"]').should('have.attr', 'aria-hidden', 'false');
  });

  it('should hide badge count when no notifications are present', () => {
    // Setup: Clear all notifications
    cy.intercept('DELETE', '/api/notifications').as('clearNotifications');
    cy.wait('@clearNotifications');

    cy.get('[data-testid="notification-count"]').should('be.visible');
    cy.get('[data-testid="notification-count"]').should('contain', '0');
    cy.get('[data-testid="notification-bell-icon"]').should('have.attr', 'aria-badge', '0');
    cy.get('[data-testid="notification-bell-icon"]').should('have.attr', 'aria-hidden', 'true');
    cy.get('[data-testid="notification-bell-icon"]').should('not.exist');
  });
});
